	[1104]={ name="Dione", english="DAVIST", stature="168CM", weight="58KG", blood=1024, birthday={11,27}, jp_voice="三浦冴子", jp_cvid=0, chn_voice="三浦冴子", chn_cvid=3205, life="The origins of Dione Goya remain a mystery. She claims to be a priestess of the Mother Earth Sect and is currently accompanying the Zulu Mercenary led by Antelope.\n\nShe connects with the world in the most direct and simple way, traversing nations and remote places. No one knows her journey's length, nor the significance of her poetic chants, and she never intends to explain.\n\nRather than narrate her own story, she prefers learning about newcomers, listening to their hardships and happiness, offering support within her means.", camp=7, hero_type=6, ele_type=4, hero_color=3, location=1, skill_list={1104,110401,110404}, init_skill_list={1104,110401,110404,110480}, inborn_skill={110480,110490}, show_model="3104", model="3104", showQ_model="3104", head="heroHead/hero_head_3104.png", show_weapon=0, img_painting="record_pic_3104.png", basic_attr={
