	[1202]={ name="Yuanya", english="Enya", stature="110CM", weight="28.4KG", blood=1024, birthday={4,2}, jp_voice="夏生", jp_cvid=0, chn_voice="夏生", chn_cvid=5205, life="The youngest and cutest genius scientist in the Lissugen branch of the Leistance Security Bureau, constantly accompanied by various snacks and sugary drinks.\n\n[Yuanya is recognized as the snack sommelier within the Bureau; whatever snacks you want to buy, ask her for sure.]\n\n[For matters unrelated to eating, she finds them bothersome. If there's something you'd like to ask her, bring delicious snacks, it'll work wonders.] \n\n[It's rumored she likes rabbits? Girls who love rabbits must possess warm and sweet hearts, right?] \n\n——Evaluations on Yuanya by Security Bureau colleagues.", camp=6, hero_type=3, ele_type=2, hero_color=3, location=3, skill_list={1202,120201,120204}, init_skill_list={1202,120201,120204,120280}, inborn_skill={120280,120290}, show_model="2501", model="2501", showQ_model="2501", head="heroHead/hero_head_2501.png", show_weapon=0, img_painting="record_pic_2501.png", basic_attr={
