	[1306]={ name="Snow Fox", english="DAVIST", stature="170CM", weight="48KG", blood=1024, birthday={11,49}, jp_voice="藤井環", jp_cvid=0, chn_voice="藤井環", chn_cvid=7605, life="Karentilo belongs to Burksomi Arctic Science Expedition Team. Diverging from other silent scholars focused solely on research, Karentilo is a unique presence as someone who constantly loves to chat in the science expedition team.\n\nHaving resided long-term in arctic ice plains alongside science expedition parents since childhood, she's intimately familiar with the ice fields, glaciers, snow foxes auroras…as mundane as the ice plains seem to others, she perceives them as vast treasure troves, as looking slightly further yields endlessly unique views.\n\nWith frequent anchor panic manifestations, the field's gradual instability becomes apparent. This time, Karentilo faces challenges possibly tougher than imagined.\n[She's a splashing color across the vast ice fields and symphony amid tranquil wilderness—a piece only she can play.]", camp=4, hero_type=1, ele_type=3, hero_color=3, location=1, skill_list={1306,130601,130604}, init_skill_list={1306,130601,130604,130680}, inborn_skill={130680,130690}, show_model="1501", model="1501", showQ_model="1501", head="heroHead/hero_head_1501.png", show_weapon=0, img_painting="record_pic_1501.png", basic_attr={
