	[1022]={ name="Rose", english="Kerry", stature="174CM", weight="48.5KG", blood=1024, birthday={11,12}, jp_voice="山本亜衣", jp_cvid=0, chn_voice="山本亜衣", chn_cvid=5605, life="Calm and suave, a mature woman famed for placing money and fine drinks above all, real name unknown, remarked with the alias [Rose] actively among Uzyanta's extensive bounty hunter realm.\nNavigating Uzyanta's both the legal and illegal worlds, she possesses a flexible moral compass as an expert money gatherer. As long as Taino Currency appropriately suffice, Rose can accomplish anything and never fails.\nShe often maintains an inscrutable grin, adept at identifying crucial verbal gaps to extract advantageous information—when commissioning, caution against excessive talk, simply paying her adequately and specifying tasks suffices.\n[Both human nature and matter possess shadows and counterparts—yet Taino bills stand alone, pure and delightful, emitting sweet fragrance.]\n[So, what's your decision on payment? Hope it merits our conversation here.]", camp=7, hero_type=3, ele_type=0, hero_color=4, location=3, skill_list={1022,102201,102204}, init_skill_list={1022,102201,102204,102280}, inborn_skill={102280,102290}, show_model="4515", model="4515", showQ_model="4515", head="heroHead/hero_head_4515.png", show_weapon=0, img_painting="record_pic_4515.png", basic_attr={
